        reach[u] = [w for w in parent if w in PARTS and w != u]
    print('  min reach', min(len(r) for r in reach.values()))
    for variant in ('relay', 'mixed', 'direct', 'chain', 'chain2'):
        for order in (0, 1):
            t0 = time.time()
